USE paper_bottle;
SET FOREIGN_KEY_CHECKS = 0;
TRUNCATE TABLE messages;
TRUNCATE TABLE conversations;
TRUNCATE TABLE pick_records;
TRUNCATE TABLE bottles;
TRUNCATE TABLE users;
SET FOREIGN_KEY_CHECKS = 1;




SELECT '=== Stats ===' AS info;
SELECT COUNT(*) AS total_users FROM users;
SELECT COUNT(*) AS total_bottles FROM bottles;
SELECT gender, COUNT(*) AS cnt FROM users GROUP BY gender;
SELECT province, COUNT(*) AS cnt FROM users GROUP BY province ORDER BY cnt DESC LIMIT 10;
